const scans = $input.all().map(({ json: row }) => {
  let report = null;
  let reportError = null;

  try {
    report = JSON.parse(row.report_json);
    if (!report || typeof report !== "object" || Array.isArray(report)) {
      throw new Error("Expected a report object");
    }
  } catch {
    report = null;
    reportError = "The saved report could not be read.";
  }

  return {
    id: row.id,
    scannedUrl: row.scanned_url,
    scanCompletedAt: row.scan_completed_at,
    scanStatus: row.scan_status,
    report,
    reportError
  };
});

scans.sort((a, b) =>
  Date.parse(b.scanCompletedAt) - Date.parse(a.scanCompletedAt)
);

return [{ json: { scans } }];

const { scans } = $input.first().json;

return [{
  json: {
    scans: scans.map(scan => {
      const report = scan.report;
      const pageReviews = report?.pageReviewCount ?? null;
      const links = report?.linkSummary;
      let displayStatus;
      let displayReason = null;

      if (scan.scanStatus === "failed") {
        displayStatus = "Scan failed";
        displayReason = report?.failureReason ?? scan.reportError;
      } else if (!report) {
        displayStatus = "Report unavailable";
        displayReason = scan.reportError;
      } else if (pageReviews > 0 || links?.broken > 0 || links?.needsReview > 0) {
        displayStatus = "Needs review";
      } else if (pageReviews === null || links?.status !== "completed" || links?.unverified > 0) {
        displayStatus = "Checks incomplete";
      } else {
        displayStatus = "No issues found in sampled checks";
      }

      return { ...scan, displayStatus, displayReason };
    })
  }
}];

const { scans } = $input.first().json;


const escape = value => String(value ?? "").replace(/[&<>"']/g, char => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
})[char]);

// Scan history is already sorted newest first.
const latestMetaCheck = new Map();

for (const scan of scans) {
  const url = scan.scannedUrl;
  if (!url || scan.scanStatus !== "completed" || latestMetaCheck.has(url)) {
    continue;
  }

  const check = scan.report?.pageChecks?.find(check =>
    check.id === "meta_description" &&
    (check.status === "pass" || check.status === "needs_review")
  );

  if (check) latestMetaCheck.set(url, check);
}

const openIssues = [...latestMetaCheck]
  .filter(([, check]) => check.status === "needs_review")
  .map(([url]) =>
    `<li><span style="color:#ef4444" aria-hidden="true">●</span>
     <strong>Missing meta description</strong> · ${escape(url)}</li>`
  )
  .join("");

// History is already sorted newest first.
const scansByUrl = new Map();
for (const scan of scans) {
  const group = scansByUrl.get(scan.scannedUrl) ?? [];
  group.push(scan);
  scansByUrl.set(scan.scannedUrl, group);
}

const fixes = {
  page_title: "Add a descriptive page title if it is also missing in the rendered page.",
  meta_description: "Add a short meta description that explains what this page offers.",
  h1_heading: "Check the rendered page for a main heading. Add a clear H1 if it is missing."
};

const cards = [...scansByUrl].map(([url, [latest, ...older]]) => {
  const report = latest.report;
  const assessed = latest.scanStatus === "completed" && Boolean(report);
  const checks = assessed ? (report.pageChecks ?? []) : [];
  const links = assessed ? report.linkSummary : null;
  const passed = checks.filter(check => check.status === "pass").length;
  const review = checks.find(check => check.status === "needs_review");
  const brokenLink = report?.linkResults?.find(link => link.status === "broken");

  const rows = checks.map(check => {
    const [style, label] = check.status === "pass" ? ["pass", "Pass"]
      : check.status === "needs_review" ? ["review", "Review"]
      : ["unknown", "Unverified"];

    return `<li><span class="badge ${style}">${label}</span>
      <div><strong>${escape(check.label)}</strong>
      <small>${escape(check.evidence)}</small></div></li>`;
  }).join("");

  const summary = assessed
    ? `${passed} of ${checks.length} page checks passed. ${
        links?.status === "completed"
          ? `${links.passed} of ${links.checked} sampled links passed; ${links.broken} broken, ${links.needsReview} need review, ${links.unverified} unverified.`
          : "Links were not checked."
      }`
    : (latest.displayReason || latest.reportError || "No usable assessment for this scan.");

  const fix = !assessed ? "Retry the scan before recommending a website change."
    : brokenLink ? `Check where this broken link should lead, then update or remove it: ${brokenLink.linkUrl}`
    : review ? (fixes[review.id] ?? "Review the evidence for this check.")
    : links?.needsReview > 0 || links?.unverified > 0
      ? "Recheck the links that need review or could not be verified."
      : "No fix identified from the checks that ran.";

  const history = older.length
    ? `<details><summary>${older.length} earlier scan(s)</summary><ul>${
        older.map(scan => `<li>${escape(scan.scanCompletedAt)} · ${
          escape(scan.displayStatus)
        }${scan.displayReason ? ` — ${escape(scan.displayReason)}` : ""}</li>`).join("")
      }</ul></details>`
    : "";

  return `<article class="site-card">
    <header><div><p class="eyebrow">LATEST SCAN</p>
    <h3>${escape(report?.title || url)}</h3>
    <small>${escape(url)} · ${escape(latest.scanCompletedAt)}</small></div>
    <span class="site-mark" aria-hidden="true">↗</span></header>
    <p><strong>AI description:</strong> ${
      escape(assessed ? (report.aiAnalysis?.summary || "Unavailable for this scan.") : "Not assessed.")
    }</p>
    ${rows ? `<ul class="checklist">${rows}</ul>` : `<p class="badge unknown">Checks unavailable</p>`}
    <p><strong>Summary:</strong> ${escape(summary)}</p>
    <p class="fix"><strong>Fix first:</strong> ${escape(fix)}</p>
    <small>Scope: fetched HTML and up to five sampled links. JavaScript was not rendered.</small>
    ${history}
  </article>`;
}).join("");



return [{ json: { html: `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>Scan History</title>
<style>
  body { font: 16px system-ui; max-width: 760px; margin: 40px auto; padding: 0 20px; }
  details { border: 1px solid #ccc; border-radius: 8px; padding: 14px; margin: 12px 0; }
  summary { cursor: pointer; overflow-wrap: anywhere; }
.site-card { border: 1px solid #777; border-radius: 14px; padding: 22px; margin: 16px 0; overflow-wrap: anywhere; }
.site-card header { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
.site-card h3 { font-size: 1.35rem; margin: 4px 0; }
.eyebrow { font-size: .72rem; letter-spacing: .15em; margin: 0; }
.site-mark { border: 1px solid #777; border-radius: 10px; padding: 10px 14px; }
.checklist { list-style: none; padding: 0; }
.checklist li { display: flex; gap: 12px; align-items: flex-start; padding: 10px 0; border-top: 1px solid #777; }
.checklist small { display: block; margin-top: 3px; }
.badge { display: inline-block; padding: 2px 8px; border-radius: 5px; font-weight: 700; white-space: nowrap; }
.pass { background: #dcfce7; color: #14532d; }
.review { background: #fee2e2; color: #7f1d1d; }
.unknown { background: #e5e7eb; color: #374151; }
.fix { border-left: 3px solid currentColor; padding-left: 12px; }
.scan-panel { border: 1px solid #777; border-radius: 14px; padding: 20px; margin: 20px 0; }
.scan-panel h2 { margin: 0 0 12px; }
.scan-panel label { display: block; font-weight: 600; margin-bottom: 6px; }
.scan-controls { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; }
.scan-controls input, .scan-controls button { font: inherit; padding: 10px 14px; border-radius: 8px; }
.scan-controls input { flex: 1 1 260px; min-width: 0; border: 1px solid #888; }
.scan-controls button { background: #222; color: white; border: 1px solid #888; cursor: pointer; }
</style></head><body>
  <h1>Scan History</h1>
  <section class="scan-panel">
  <h2>Scan a page</h2>
 <form method="post"
      action="http://localhost:5678/webhook/scan-website"
      target="_top">
    <label for="website-url">Website URL</label>
    <div class="scan-controls">
      <input id="website-url" name="websiteUrl" type="url"
             placeholder="https://books.toscrape.com/" required>
      <button type="submit">Scan page ↗</button>
    </div>
  </form>
  <small>For now, enter a Books to Scrape URL. Confirmation opens in a new tab.
    Reopen this dashboard after the scan finishes to see the result.</small>
</section>
  <h2>Open issues</h2>
${openIssues ? `<ul>${openIssues}</ul>` : "<p>No open meta description issues in saved scans.</p>"}
<h2>Saved scans</h2>
  <p>${scans.length} saved scans · newest first</p>
  ${cards || "<p>No scans saved yet.</p>"}
</body></html>` } }];
